    details: "・t-SNE：高次元データの可視化（2次元・3次元プロット）に極めて優れるが、計算コストが高く新規データの追加射影が難しい。\n・UMAP：位相幾何学（トポロジー）に基づき、t-SNEより高速かつ大域的な構造も保ちやすい最新の次元削減手法。\n・Isomap（測地線距離を用いた多次元尺度構成法）と LLE（Locally Linear Embedding：近傍点の線形結合関係を保持する多様体学習）。\n・自己組織化マップ（SOM / コホーネン）：大脳皮質の視覚野を模した2層ニューラルネットによる教師なし次元削減・可視化手法。",
    tags: ["教師なし学習", "次元削減", "頻出"]
