    details: "全取引数を N とするとき、ルール「X ⇒ Y」の3指標：\n1. 支持度（Support）= P(X ∩ Y) = (XとYを両方買った件数) / N （全体の何割で起きたか）\n2. 確信度（信頼度 / Confidence）= P(Y | X) = (XとYを両方買った件数) / (Xを買った件数) （Xを買った人のうち何割がYも買ったか）\n3. リフト値（Lift）= Confidence / P(Y) = P(X ∩ Y) / (P(X)P(Y)) （単独でYが売れる確率に比べて何倍売れやすくなったか）。効率的な探索には「Aprioriアルゴリズム」が使われる。",
