    details: "・データリーケージの代表例：\n  1. 分割前に全データで前処理（標準化・欠損値の平均値補完・オーバーサンプリングSMOTE）を行ってしまう。\n  2. 時系列データでランダムに交差検証を行い、未来のデータで過去を予測してしまう。\n  3. 目的変数（結果）確定後に記録されるIDやフラグを説明変数に入れてしまう。\n・欠損値補完の代表手法：平均値・中央値・最頻値による単一代入法のほか、他の説明変数から回帰モデル等で欠損値を反復予測して複数の補完データセットを作る「多重代入法（MICE：Multiple Imputation by Chained Equations）」がある。",
