    details: "・CEC（Constant Error Carousel）：線形な自己ループにより誤差勾配を消さずに過去から未来へ運ぶベルトコンベアの役割を果たす。\n・忘却ゲート（Forget Gate）：過去の記憶セルの情報をどれだけ残し、どれだけ忘れるかを決める（Gers et al., 1999/2000で導入）。\n・入力ゲート（Input Gate）：現在の新しい入力情報をどれだけ記憶セルに書き込むかを決める。\n・出力ゲート（Output Gate）：記憶セルの情報をどれだけ現在の隠れ状態として出力するかを決める。\n・覗き穴結合（Peephole Connection）：各ゲートがCEC（記憶セル）の内部状態を直接参照できるようにした改良。",
