    details: "・Self-Attention（自己注意機構）：同じ文の中の単語同士（例：「それ（代名詞）」が文中のどの名詞を指すか）の関連度を Query(Q), Key(K), Value(V) の3つのベクトルを用いて Attention(Q,K,V) = softmax(QK^T / √d_k)V で計算する。\n・Multi-Head Attention：Q, K, V を複数の異なる部分空間（ヘッド）に分割して並列にAttentionを計算することで、文法関係や意味関係など複数の異なる視点から関連性を捉える。\n・Decoder側の Masked Multi-Head Attention：翻訳や文章生成時に「カンニング（未来の単語を見ること）」を防ぐため、現在より後ろの単語のAttention重みを −∞（確率0）にマスクする。",
    tags: ["Transformer", "自然言語処理", "モデル名鑑", "超頻出"]
