    trap: "最頻出の『LoRA（Low-Rank Adaptation）』の仕組み：「元の重み行列 W (d×k) を固定し、それと並列にランク r (r ≪ d, k) の2つの小さな低ランク行列 A (r×k) と B (d×r) の積 ΔW = BA を追加して A と B だけを学習する。推論時は元の重みに足し合わせられるため『推論時の追加遅延（レイテンシ）がゼロ』になる」！",
