    summary: "TransformerのFFN（順伝播層）を複数の「Expert（専門家サブネットワーク）」に分割し、各トークンごとにルーター（ゲート）が選んだ少数のExpert（例：8個中2個）だけを活性化して処理するスパース構造。",
