    trap: "Function Calling（ツール呼び出し）において、「LLM自身が直接外部サーバーのプログラムコードを実行してデータベースを書き換える」のではなく、『LLMは呼び出すべき関数名と引数（JSON形式）を出力し、それを受け取ったアプリケーション側が実際のAPIを実行して結果をLLMに返す』という役割分担に注意！",
    details: "・AIエージェントの構成要素：①プランニング（タスク分解・自己反省 Self-Reflection）、②メモリ（短期記憶＝コンテキストウィンドウ、長期記憶＝外部ベクトルDB等）、③ツール利用（Web検索、DBクエリ、コードインタープリタ等）。\n・MCP（Model Context Protocol / Anthropic提唱）：LLMアプリケーションと外部のデータソースやツール（Googleドライブ、Slack、DB、ローカルファイル等）を共通の規格で安全に接続するためのオープン標準プロトコル（「AIにとってのUSB-Cポート」に例えられる）。",
